const deleteAnalyticsEventsOutsidePlans = `-- name: DeleteAnalyticsEventsOutsidePlans :execrows
DELETE FROM analytics_events
WHERE id IN (
    SELECT e.id FROM analytics_events e
    JOIN accounts a ON a.id = e.account_id
    WHERE NOT (a.plan::text = ANY($1::text[]))
    ORDER BY e.at
    LIMIT $2::int
)
`

type DeleteAnalyticsEventsOutsidePlansParams struct {
	KnownPlans []string
	MaxRows    int32
}

// Deletes up to max_rows events of accounts on a plan without analytics
// retention in known_plans.
func (q *Queries) DeleteAnalyticsEventsOutsidePlans(ctx context.Context, db DBTX, arg DeleteAnalyticsEventsOutsidePlansParams) (int64, error) {
	result, err := db.Exec(ctx, deleteAnalyticsEventsOutsidePlans, arg.KnownPlans, arg.MaxRows)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const deleteExpiredAnalyticsEventsForPlan = `-- name: DeleteExpiredAnalyticsEventsForPlan :execrows
DELETE FROM analytics_events
WHERE id IN (
    SELECT e.id FROM analytics_events e
    JOIN accounts a ON a.id = e.account_id
    WHERE e.at < $1::timestamptz AND a.plan::text = $2::text
    ORDER BY e.at
    LIMIT $3::int
)
`

